package dev.danielc.fujiapp;
import android.graphics.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FujiPhotoCardTest {
 @Test public void focalLengthFormatsRationalWithoutInventingMissingValues(){assertEquals("35 mm",PhotoDetails.focalLength("350/10"));assertEquals("23.5 mm",PhotoDetails.focalLength("23.5"));for(String value:new String[]{"","unknown","0","1/0","-23"})assertEquals("",PhotoDetails.focalLength(value));}
 @Test public void noteIsIncludedInImmutableExportSnapshot(){PhotoFrame.Options options=new PhotoFrame.Options();options.filmNote="Classic Chrome / My custom look";PhotoFrame.Options snapshot=options.copy();options.filmNote="Changed";assertEquals("Classic Chrome / My custom look",snapshot.filmNote);}
 @Test public void cardsPreservePhotoAndHideExifWhenRequested(){Bitmap source=Bitmap.createBitmap(1000,600,Bitmap.Config.ARGB_8888);source.eraseColor(Color.RED);PhotoDetails details=new PhotoDetails();details.fuji.settings.put("simulation","Nostalgic Negative");details.camera="X-E5";details.lens="XF 23mm";details.aperture="f/2";details.shutter="1/125 s";details.iso="125";details.exposure="f/2 1/125s ISO 125";details.takenAt="2026:10:11 12:00:00";for(int style:FujiPhotoCard.STYLES){PhotoFrame.Options o=new PhotoFrame.Options();o.style=style;o.filmNote="Classic Chrome";o.author="Photographer";Bitmap visible=PhotoFrame.render(source,details,o);assertEquals(Color.RED,visible.getPixel(visible.getWidth()/2,400));o.parameters=false;Bitmap hidden=PhotoFrame.render(source,details,o);boolean differs=false;for(int y=870;y<1000;y+=2)for(int x=60;x<1040;x+=2)if(visible.getPixel(x,y)!=hidden.getPixel(x,y))differs=true;assertTrue(differs);assertFalse(source.isRecycled());visible.recycle();hidden.recycle();}source.recycle();}
 @Test public void originalSampleContactSheet()throws Exception{android.content.Context context=org.robolectric.RuntimeEnvironment.getApplication();BitmapFactory.Options decode=new BitmapFactory.Options();decode.inSampleSize=4;Bitmap source;try(java.io.InputStream in=context.getAssets().open("studio/coast.png")){source=BitmapFactory.decodeStream(in,null,decode);}PhotoDetails d=new PhotoDetails();d.fuji.settings.put("simulation","Reala ACE");d.camera="X-E5";d.lens="XF 23mm F2";d.aperture="f/2";d.shutter="1/125 s";d.iso="125";d.exposure="f/2  1/125s  ISO 125";d.focalLength="23 mm";d.takenAt="2026:10:11";Bitmap sheet=Bitmap.createBitmap(1800,950,Bitmap.Config.ARGB_8888);sheet.eraseColor(0xff242a2c);Canvas canvas=new Canvas(sheet);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);for(int i=0;i<3;i++){PhotoFrame.Options o=new PhotoFrame.Options();o.style=FujiPhotoCard.STYLES[i];o.paper=1;o.title="EXIF DEMO / 示例参数";o.author="FUJI GALLERY";o.filmNote="Classic Chrome / 示例备注";Bitmap frame=PhotoFrame.render(source,d,o);float scale=Math.min(540f/frame.getWidth(),810f/frame.getHeight()),w=frame.getWidth()*scale,h=frame.getHeight()*scale;canvas.drawBitmap(frame,null,new RectF(i*600+300-w/2,440-h/2,i*600+300+w/2,440+h/2),paint);paint.setColor(Color.WHITE);paint.setTextSize(25);paint.setTextAlign(Paint.Align.CENTER);canvas.drawText(PhotoFrame.NAMES[o.style],i*600+300,920,paint);frame.recycle();}java.io.File folder=new java.io.File("build/reports/frame-catalog");assertTrue(folder.isDirectory()||folder.mkdirs());try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(folder,"FujiGallery-zh62-fuji-cards.png"))){assertTrue(sheet.compress(Bitmap.CompressFormat.PNG,100,out));}source.recycle();sheet.recycle();}
}
